 fn reserve_demand(storage:&Self::Storage,index:usize)->Result<Option<RetirementDemand>,ValueError>{let entry=storage.patches.entries.get(index).ok_or_else(invalid)?;if storage.patches.length!=index+usize::from(entry.retirement.is_some()){return Err(invalid())}Ok(entry.retirement.is_none().then(||fixed(size_of::<UiTurnPatchRetireSlot>()+size_of::<UiTurnPatchRetireKey>()+2*size_of::<usize>()+size_of::<u64>())))}
 fn reserve_step(storage:&mut Self::Storage,index:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{let mut work=0;let result=(||{let Some(d)=Self::reserve_demand(storage,index)?else{return Ok(Default::default())};if !retained_clone_grant_admits(g,d){return Ok(Default::default())}let mut arena=match UI_TURN_PATCH_RETIRE_ARENA.try_lock(){Ok(arena)=>arena,Err(std::sync::TryLockError::WouldBlock)=>return Ok(Default::default()),Err(std::sync::TryLockError::Poisoned(_))=>return Err(invalid())};if arena.epoch_exhausted{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original turn patch retirement epochs exhausted"))}let slot=storage.candidate;if slot>=UI_TURN_PATCH_RETIRE_SLOTS{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original turn patch retirement slots exhausted"))}work=1;storage.candidate+=1;if !arena.slots[slot].reserved{let epoch=arena.next_epoch;arena.slots[slot].epoch=epoch;arena.slots[slot].reserved=true;match epoch.checked_add(1){Some(next)=>arena.next_epoch=next,None=>arena.epoch_exhausted=true}storage.patches.entries[index].retirement=Some(UiTurnPatchRetireKey{slot,epoch});storage.patches.length=index+1;storage.candidate=0;}Ok(receipt(d))})();RetainedWorkOutcome{result,work}}
