 fn push_step(storage:&mut Self::Storage,index:usize,input:&mut Option<UiPatch>,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<RetainedCloneProgress>>{let mut work=0;let result=(||{let d=fixed(Self::push_copy_bytes(storage,index)?);if !retained_clone_grant_admits(g,d){return Ok(None)}if storage.patches.length!=index+1{return Err(invalid())}let entry=storage.patches.entries.get_mut(index).ok_or_else(invalid)?;if entry.retirement.is_none()||!entry.contents.terminal_is_empty(){return Err(invalid())}let out=entry.contents.pending.source_mut().map_err(|_|invalid())?;if out.is_some()||input.is_none(){return Err(invalid())}work=1;*out=input.take();Ok(Some(receipt(d)))})();RetainedWorkOutcome{result,work}}
